# Compile the actual foundation implementation against a tiny in-memory world.
import pathlib,tempfile,subprocess,os
root=pathlib.Path(__file__).resolve().parent
sources={
'net/minecraft/block/material/Material.java':'''package net.minecraft.block.material;public class Material {public boolean solid,replace,liquid;public Material(boolean s,boolean r,boolean l){solid=s;replace=r;liquid=l;}public boolean isSolid(){return solid;}public boolean isReplaceable(){return replace;}public boolean isLiquid(){return liquid;}}''',
'net/minecraft/util/ResourceLocation.java':'''package net.minecraft.util;public class ResourceLocation {String id;public ResourceLocation(String s){id=s;}public String getResourcePath(){return id;}}''',
'net/minecraft/util/Rotation.java':'''package net.minecraft.util;public enum Rotation {NONE}''',
'net/minecraft/util/math/BlockPos.java':'''package net.minecraft.util.math;public class BlockPos {public int x,y,z;public BlockPos(int x,int y,int z){this.x=x;this.y=y;this.z=z;}public int getY(){return y;}public BlockPos down(int d){return new BlockPos(x,y-d,z);}public boolean equals(Object o){if(!(o instanceof BlockPos))return false;BlockPos p=(BlockPos)o;return x==p.x&&y==p.y&&z==p.z;}public int hashCode(){return x*737+y*37+z;}}''',
'net/minecraft/block/Block.java':'''package net.minecraft.block;import net.minecraft.block.state.IBlockState;import net.minecraft.block.material.Material;import net.minecraft.util.ResourceLocation;public class Block {String id;public IBlockState state;public Block(String id,boolean full,Material m){this.id=id;state=new IBlockState(this,full,m);}public ResourceLocation getRegistryName(){return new ResourceLocation(id);}public IBlockState getDefaultState(){return state;}public boolean hasTileEntity(IBlockState s){return false;}}''',
'net/minecraft/block/state/IBlockState.java':'''package net.minecraft.block.state;import net.minecraft.block.Block;import net.minecraft.block.material.Material;import net.minecraft.util.Rotation;public class IBlockState {Block b;boolean full;Material m;public IBlockState(Block b,boolean f,Material m){this.b=b;full=f;this.m=m;}public Block getBlock(){return b;}public Material getMaterial(){return m;}public boolean isFullCube(){return full;}public IBlockState withRotation(Rotation r){return this;}}''',
'net/minecraft/init/Blocks.java':'''package net.minecraft.init;import net.minecraft.block.*;import net.minecraft.block.material.Material;public class Blocks {public static Block STONE=new Block("stone",true,new Material(true,false,false)),AIR=new Block("air",false,new Material(false,true,false)),WATER=new Block("water",false,new Material(false,false,true));}''',
'net/minecraft/world/World.java':'''package net.minecraft.world;import java.util.*;import net.minecraft.block.state.*;import net.minecraft.util.math.BlockPos;import net.minecraft.init.Blocks;public class World {public boolean isRemote;public int ground=10;public Map<BlockPos,IBlockState> cells=new HashMap<>();public boolean isBlockLoaded(BlockPos p){return true;}public Object getTileEntity(BlockPos p){return null;}public IBlockState getBlockState(BlockPos p){return cells.getOrDefault(p,p.y<=ground?Blocks.STONE.state:Blocks.AIR.state);}public boolean isAirBlock(BlockPos p){return getBlockState(p).getBlock()==Blocks.AIR;}public boolean setBlockState(BlockPos p,IBlockState s,int f){cells.put(p,s);return true;}}''',
'org/sonicraft/backport/Content.java':'''package org.sonicraft.backport;import java.util.*;import net.minecraft.block.Block;public class Content {public static Map<String,Block> BLOCKS=new HashMap<>();}''',
'org/sonicraft/backport/SonicraftLegacy.java':'''package org.sonicraft.backport;public class SonicraftLegacy {public static C config=new C();public static class C {public boolean getBoolean(String a,String b,boolean v,String c){return v;}public int getInt(String a,String b,int v,int lo,int hi,String c){return v;}}}''',
'org/sonicraft/backport/StructurePort.java':'''package org.sonicraft.backport;import java.util.*;import net.minecraft.block.state.IBlockState;import net.minecraft.util.Rotation;import net.minecraft.util.math.BlockPos;public class StructurePort {public static class Cell {int x,y,z;IBlockState block;Cell(int x,int y,int z,IBlockState b){this.x=x;this.y=y;this.z=z;block=b;}}public static class Template {String name;List<Cell> blocks=new ArrayList<>();Template(String n){name=n;}}public static BlockPos at(Template t,BlockPos p,Cell c,Rotation r){return new BlockPos(p.x+c.x,p.y+c.y,p.z+c.z);}}''',
'org/sonicraft/backport/FoundationTest.java':'''package org.sonicraft.backport;import net.minecraft.block.*;import net.minecraft.block.material.Material;import net.minecraft.init.Blocks;import net.minecraft.util.*;import net.minecraft.util.math.*;import net.minecraft.world.World;public class FoundationTest {static void eq(int got,int expected){if(got!=expected)throw new AssertionError(got+" != "+expected);}static int run(World w,StructurePort.Template t){return StructureFoundation.fill(w,new BlockPos(0,30,0),t,Rotation.NONE);}public static void main(String[] args){StructurePort.Template t=new StructurePort.Template("studiopolis_building");t.blocks.add(new StructurePort.Cell(0,0,0,Blocks.STONE.state));eq(run(new World(),t),19);World deep=new World();deep.ground=-30;eq(run(deep,t),0);World wet=new World();wet.cells.put(new BlockPos(0,29,0),Blocks.WATER.state);eq(run(wet,t),0);t.name="sky_sanctuary_island";eq(run(new World(),t),0);t.name="studiopolis_building";Block column=new Block("studiopolis_pillar",false,new Material(true,false,false));t.blocks.add(new StructurePort.Cell(2,5,0,column.state));t.blocks.add(new StructurePort.Cell(4,5,0,Blocks.STONE.state));World uneven=new World();eq(run(uneven,t),43);if(uneven.getBlockState(new BlockPos(2,11,0)).getBlock()!=column)throw new AssertionError("column material lost");if(!uneven.isAirBlock(new BlockPos(4,29,0)))throw new AssertionError("upper floor filled");System.out.println("PASS foundation: 19-block gap, deep void, liquid, floating island, elevated narrow column, upper floor exclusion");}}'''
}
for name in ['BlockDoor','BlockSlab','BlockStairs']:sources['net/minecraft/block/'+name+'.java']='package net.minecraft.block;public class '+name+' extends Block {public '+name+'(){super("test",true,new net.minecraft.block.material.Material(true,false,false));}}'
with tempfile.TemporaryDirectory() as work:
 work=pathlib.Path(work)
 for name,data in sources.items():
  p=work/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(data)
 p=work/'org/sonicraft/backport/StructureFoundation.java';p.write_text((root/'src/org/sonicraft/backport/StructureFoundation.java').read_text())
 subprocess.run(['javac','-d',str(work),*map(str,work.rglob('*.java'))],check=True)
 subprocess.run(['java','-cp',str(work),'org.sonicraft.backport.FoundationTest'],check=True)
